from netmiko import ConnectHandler
import sys

ROUTERS = {
    "HQ": "192.168.122.6",
    "Branch1": "192.168.122.5",
    "Branch2": "192.168.122.7",
}

def conn(host):
    return ConnectHandler(device_type="vyos", host=host, username="vyos", password="test")

def run_show(name, cmds):
    c = conn(ROUTERS[name])
    print(f"========== {name} ==========")
    for cmd in cmds:
        print(f"--- {cmd} ---")
        print(c.send_command(cmd))
    c.disconnect()

if __name__ == "__main__":
    cmds = [
        "show interfaces",
        "show ip ospf neighbor",
        "show ip route",
        "show configuration commands | grep ospf",
        "show configuration commands | grep interfaces",
        "show configuration commands | grep 'protocols static'",
    ]
    for r in ROUTERS:
        run_show(r, cmds)

